/**
 * Returns the canonical list of countries and cities Presentail can
deliver to, including their isActive flags, currency, flag emoji
and display ordering. Consumed by the mobile app on launch so
toggling a country or city in the backend (no app update
required) is reflected on the next launch.

 * @summary List supported delivery countries and cities
 */
export const GetDeliveryLocationsResponse = zod.object({
  countries: zod.array(
    zod.object({
      id: zod.string(),
      name: zod.string(),
      code: zod.string().describe("ISO 3166-1 alpha-2 country code."),
      flag: zod.string().describe("Flag emoji or icon for the country."),
      currency: zod
        .string()
        .describe("ISO 4217 currency code used by default for this country."),
      isActive: zod.boolean(),
      cities: zod.array(
        zod.object({
          id: zod.string(),
          name: zod.string(),
          isActive: zod.boolean(),
          fee: zod
            .number()
            .optional()
            .describe("Delivery fee in the country's native currency."),
          expressAvailable: zod
            .boolean()
            .optional()
            .describe(
              "Whether express\/same-day delivery is available for this city.",
            ),
          expressDeliveryLabel: zod
            .string()
            .optional()
            .describe(
              'Human-readable express delivery promise for this city (e.g. \"Arrives in 90 minutes\").',
            ),
          sameDayCutoffHour: zod
            .number()
            .optional()
            .describe(
              "Hour of day (0–23, local time) after which same-day delivery cannot be booked.",
            ),
          timeSlots: zod
            .array(
              zod.object({
                label: zod
                  .string()
                  .describe(
                    'Human-readable slot label (e.g. \"Morning (9 AM – 12 PM)\").',
                  ),
                cutoffHour: zod
                  .number()
                  .describe(
                    "Hour of day (0–23) after which this slot can no longer be booked for same-day delivery.",
                  ),
                extraFee: zod
                  .number()
                  .optional()
                  .describe(
                    "Additional surcharge (USD) for booking this slot, e.g. a night-delivery fee.",
                  ),
              }),
            )
            .optional()
            .describe(
              "Available delivery time slots for this city. Empty array means slots are not yet configured.",
            ),
          localizedNames: zod
            .object({
              ar: zod.string().optional(),
              fr: zod.string().optional(),
            })
            .optional()
            .describe(
              'Optional translations of a display name. Keys are lowercase\nISO 639-1 language codes (\"ar\", \"fr\"). English is implicit in\nthe parent\'s `name` field. Missing translations should fall\nback to `name`.\n',
            ),
        }),
      ),
      preferredDefaultCityId: zod
        .string()
        .optional()
        .describe("Optional id of the city to highlight as the default."),
      localizedNames: zod
        .object({
          ar: zod.string().optional(),
          fr: zod.string().optional(),
        })
        .optional()
        .describe(
          'Optional translations of a display name. Keys are lowercase\nISO 639-1 language codes (\"ar\", \"fr\"). English is implicit in\nthe parent\'s `name` field. Missing translations should fall\nback to `name`.\n',
        ),
    }),
  ),
});

/**
 * Returns the canonical list of supported display currencies (symbol,
decimals, formatting hints, base USD rates) and the country → currency
map used to auto-pick a currency for a visitor. The web storefront
uses this as the single source of truth — the same list mobile ships.

 * @summary List supported display currencies and FX metadata
 */
export const GetCurrenciesResponse = zod.object({
  currencies: zod.array(
    zod.object({
      code: zod.string(),
      name: zod.string(),
      flag: zod.string(),
      symbol: zod.string(),
      symbolPosition: zod.enum(["left", "right"]),
      spaceBetween: zod.boolean(),
      rate: zod
        .number()
        .describe(
          "Static fallback FX rate vs USD; live rates come from \/fx\/rates.",
        ),
      decimals: zod.number(),
    }),
  ),
  fallbackCode: zod.string(),
  countryToCurrency: zod.record(zod.string(), zod.string()),
});

/**
 * Returns the static catalog metadata that mobile bundles offline:
category and occasion definitions (with localized-friendly slugs,
icons and asset paths) and the curated brand list. Image fields
carry an `asset` path (resolved by clients to their local
`catalog/` tree) or a hosted `uri`.

 * @summary Catalog metadata (categories, occasions, brands)
 */
export const GetCatalogMetadataResponse = zod.object({
  categories: zod.array(
    zod.object({
      id: zod.string(),
      name: zod.string(),
      icon: zod.string(),
      image: zod
        .union([
          zod
            .object({
              asset: zod.string().optional(),
              uri: zod.string().optional(),
            })
            .describe(
              "Reference to an image asset. Either `asset` (relative path under\nthe client's bundled `catalog\/` tree) or `uri` (hosted URL) is\npresent.\n",
            ),
          zod.null(),
        ])
        .optional(),
    }),
  ),
  occasions: zod.array(
    zod.object({
      id: zod.string(),
      name: zod.string(),
      icon: zod.string(),
      description: zod.string().optional(),
      image: zod
        .union([
          zod
            .object({
              asset: zod.string().optional(),
              uri: zod.string().optional(),
            })
            .describe(
              "Reference to an image asset. Either `asset` (relative path under\nthe client's bundled `catalog\/` tree) or `uri` (hosted URL) is\npresent.\n",
            ),
          zod.null(),
        ])
        .optional(),
    }),
  ),
  brands: zod.array(
    zod.object({
      name: zod.string(),
      slug: zod.string(),
    }),
  ),
});

